        <div
          style="text-align: center; margin-bottom: 20px; font-size: 0.9em; color: #aaa; font-family: 'Cinzel', serif"
          id="m-sub"
        ></div>

        <div class="section-title">Effect</div>
        <div class="effect-box" id="m-effect"></div>

        <div class="section-title">Lore</div>
        <div class="desc-box" id="m-desc"></div>

        <div
          style="
            padding: 15px;
            background: rgba(156, 39, 176, 0.15);
            border-left: 4px solid #9c27b0;
