        padding: 0;
        justify-content: space-between;
        border: none;
      }

      .et-eye-gold {
        margin: 0;
        width: 30px;
        height: 30px;
      }

      .et-v-text {
        writing-mode: horizontal-tb;
      }

      .et-rip-edge {
        display: none;
      }

      .et-main-wrapper {
        width: 100%;
        min-height: 480px;
        display: grid;
        grid-template-areas: "card";
      }

      .et-face {
        min-height: 100%;
        width: 100%;
        border-radius: 0 0 4px 4px;
      }

      .et-toggle-v9:checked+.et-container-v9 .et-stub {
        transform: translateY(-60px);
        opacity: 0;
      }

      .et-toggle-v9:checked+.et-container-v9 .et-main-wrapper {
        transform: rotateY(-180deg);
      }

      .et-stamp-real-v9 {
        top: 45px;
        right: 10px;
        transform: rotate(20deg);
        z-index: 30;
      }

      .et-french-watermark-v9 {
        font-size: 2.72em;
        top: 20px;
        white-space: normal;
        line-height: 1.1;
      }
    }
