atData.事件 === 'object') ? statData.事件 : {}; const ticketRuntime = (eventVars.车票注入记录 && typeof eventVars.车票注入记录 === 'object') ? eventVars.车票注入记录 : {}; const ticketKey = hashTicketKey(titleRaw, storyRaw); if (ticketRuntime[ticketKey] === true) { showToast('该车票已被发放过', 'info'); return; } const heroData = (statData.主角 && typeof statData.主角 === 'object') ? statData.主角 : {}; const backpack = (heroData.背包 && typeof heroData.背包 === 'object') ? heroData.背包 : {}; await helper.insertOrAssignVariables({ stat_data: { ...statData, 事件: { ...eventVars, 车票注入记录: { ...ticketRuntime, [ticketKey]: true } }, 主角: { ...heroData, 背包: { ...backpack, [itemName]: ticketData } } } }, scope); showToast(`已自动注入 ${itemName}`, 'success'); } catch (err) { console.error('Ticket MVU Auto Import Error:', err); showToast(`自动注入失败: ${err?.message || String(err)}`, 'error'); } }; queueMicrotask(run); })();</script>
  <script>(() => {
      const helper = window.TavernHelper || window.parent?.TavernHelper || window;
      const script = document.currentScript;
      let root = script?.previousElementSibling;
      while (root && !root.classList?.contains('et-layout-wrap-v9')) root = root.previousElementSibling;
