      const STORE_KEY = 'calendar_float_ticket_alpha_store';
      const MESSAGE_KEY = 'calendar_float_ticket_alpha_latest';
      const TIME_PATH = 'stat_data.世界.时间';
      const LOCATION_PATH = 'stat_data.世界.地点';
      const parseMessageId = value => {
        const parsed = Number.parseInt(String(value ?? '').trim(), 10);
        return Number.isInteger(parsed) && parsed >= 0 ? parsed : null;
      };
      const readMessageIdFromElement = element => {
        if (!element || typeof element.closest !== 'function') return null;
        const messageElement = element.closest('.mes[mesid], [mesid], [data-message-id], [data-mes-id], [data-message_id], [data-messageid]');
        if (!messageElement) return null;
        const attrNames = ['mesid', 'data-message-id', 'data-mes-id', 'data-message_id', 'data-messageid'];
        for (const attrName of attrNames) {
          const id = parseMessageId(messageElement.getAttribute(attrName));
          if (id !== null) return id;
        }
        return null;
      };
      const resolveMessageId = currentRoot => {
        const directId = readMessageIdFromElement(currentRoot);
        if (directId !== null) return directId;

        const frame = window.frameElement;
        const frameId = readMessageIdFromElement(frame);
        if (frameId !== null) return frameId;

        const frameName = String(frame?.getAttribute?.('name') || frame?.id || '');
        const nameMatch = frameName.match(/(?:mes|message|iframe)[_-]?(\d+)/i);
        const nameId = nameMatch ? parseMessageId(nameMatch[1]) : null;
