        const eventVars = isPlainObject(statData.事件) ? statData.事件 : {};
        const ticketRuntime = isPlainObject(eventVars.车票注入记录) ? eventVars.车票注入记录 : {};
        const heroData = isPlainObject(statData.主角) ? statData.主角 : {};
